import sys
data = sys.stdin.read().split()
if data:
    x = int(data[0])
    if x < 2: print(x); sys.exit(0)
    l, r = 1, x // 2
    ans = 1
    while l <= r:
        mid = (l + r) // 2
        if mid * mid <= x:
            ans = mid
            l = mid + 1
        else:
            r = mid - 1
    print(ans)
